<voice name='ウィロー' class='ウィロー' src='voice/mc02/0160010b00'>
//「……〝<RUBY text='ゴールデン・ドーン'>黄金の夜明け</RUBY>〟……
//　それが作戦名か？」
"The Golden Dawn... That's the name of the plan?"

pt:
//【ウィロー】
<voice name='ウィロー' class='ウィロー' src='voice/mc02/0160010b00'>
//「……〝<RUBY text='ゴールデン・ドーン'>黄金の夜明け</RUBY>〟……
//　それが作戦名か？」
"A Aurora Dourada... É esse o nome do plano?"

en:
