<voice name='キャノン' class='キャノン' src='voice/mc02/0160020b03'>
//「はい」
"Yes, sir."

pt:
//【キャノン】
<voice name='キャノン' class='キャノン' src='voice/mc02/0160020b03'>
//「はい」
"Sim, senhor."

